;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Pac-Man Movement System for MSX
;; Generated by MSX Retro Game IDE
;;
;; Implements advanced Pac-Man style movement with:
;; - Pixel-perfect movement at 60fps
;; - Collision checks every 8 pixels (tile boundaries)
;; - Direction intention system (desired vs current)
;; - Perpendicular vs opposite direction logic
;; - 8-pixel character grid alignment
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; Direction constants
DIRECTION_NONE          EQU 0
DIRECTION_LEFT          EQU 1
DIRECTION_RIGHT         EQU 2
DIRECTION_UP            EQU 3
DIRECTION_DOWN          EQU 4

; Velocity mapping for directions
DIR_VELOCITY_TABLE:
    DB 0, 0         ; NONE: vx=0, vy=0
    DB -1, 0        ; LEFT: vx=-1, vy=0
    DB 1, 0         ; RIGHT: vx=1, vy=0
    DB 0, -1        ; UP: vx=0, vy=-1
    DB 0, 1         ; DOWN: vx=0, vy=1

; Opposite direction table
OPPOSITE_DIR_TABLE:
    DB 0, 2, 1, 4, 3  ; NONE->NONE, LEFT->RIGHT, RIGHT->LEFT, UP->DOWN, DOWN->UP

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Pac-Man Movement System - Main update function
;; Input: None
;; Output: None
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
PACMAN_MOVEMENT_SYSTEM:
    LD B, 0                     ; B = current entity ID

PACMAN_MOVEMENT_LOOP:
    LD A, B
    CP MAX_ENTITIES
    RET NC                      ; Done with all entities
    
    ; Check if entity is active
    CALL GET_ENTITY_PTR
    LD A, (HL)
    OR A
    JP Z, PACMAN_MOVEMENT_NEXT
    
    ; Check if entity has pacMovement component
    LD A, B
    LD C, COMP_ID_PACMOVEMENT
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, PACMAN_MOVEMENT_NEXT  ; No pacMovement component
    
    ; Check if movement is enabled
    PUSH HL
    LD BC, 10                   ; Offset to isEnabled flag
    ADD HL, BC
    LD A, (HL)
    POP HL
    OR A
    JP Z, PACMAN_MOVEMENT_NEXT  ; Movement disabled
    
    LD (PAC_MOVEMENT_PTR), HL   ; Save component pointer
    LD A, B
    LD (PAC_CURRENT_ENTITY), A
    
    ; Get entity's position component
    LD A, B
    LD C, COMP_ID_POSITION
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    JP Z, PACMAN_MOVEMENT_NEXT  ; No position component
    LD (PAC_POSITION_PTR), HL
    
    ; Get player input component (if exists)
    LD A, B
    LD C, COMP_ID_PLAYER_INPUT
    CALL GET_ENTITY_COMPONENT
    LD (PAC_INPUT_PTR), HL      ; May be null if not player controlled
    
    ; Process Pac-Man movement logic
    CALL PROCESS_PACMAN_INPUT
    CALL UPDATE_PACMAN_MOVEMENT
    CALL UPDATE_PACMAN_ROTATION

PACMAN_MOVEMENT_NEXT:
    INC B
    JP PACMAN_MOVEMENT_LOOP

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Process input for desired direction
;; Input: Component pointers set in variables
;; Output: Updates desiredDirection in component
;; Destroys: AF, BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
PROCESS_PACMAN_INPUT:
    LD HL, (PAC_INPUT_PTR)
    LD A, H
    OR L
    RET Z                       ; No input component
    
    ; Check if input is enabled
    INC HL                      ; Skip controllerId
    LD A, (HL)
    OR A
    RET Z                       ; Input disabled
    
    ; Read keyboard/joystick input
    CALL READ_PLAYER_INPUT      ; Returns direction in A
    OR A
    RET Z                       ; No input
    
    ; Store desired direction in pacMovement component
    LD HL, (PAC_MOVEMENT_PTR)
    INC HL                      ; Skip speed
    INC HL                      ; Skip currentDirection
    LD (HL), A                  ; Set desiredDirection
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Update Pac-Man movement logic
;; Input: Component pointers set in variables
;; Output: Updates position and movement state
;; Destroys: All registers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
UPDATE_PACMAN_MOVEMENT:
    LD HL, (PAC_MOVEMENT_PTR)
    
    ; Get movement parameters
    LD A, (HL)                  ; speed
    LD (PAC_SPEED), A
    INC HL
    LD A, (HL)                  ; currentDirection
    LD (PAC_CURRENT_DIR), A
    INC HL
    LD A, (HL)                  ; desiredDirection
    LD (PAC_DESIRED_DIR), A
    INC HL
    LD A, (HL)                  ; pixelCounter
    LD (PAC_PIXEL_COUNTER), A
    
    ; Check if we're at a tile boundary (pixelCounter == 0)
    OR A
    JP NZ, CONTINUE_CURRENT_MOVEMENT ; Not at boundary, keep moving
    
    ; At tile boundary - check if we can change direction
    CALL CHECK_DIRECTION_CHANGE
    
CONTINUE_CURRENT_MOVEMENT:
    ; Move in current direction
    LD A, (PAC_CURRENT_DIR)
    OR A
    RET Z                       ; No movement if direction is NONE
    
    ; Check collision in current direction before moving
    CALL CHECK_WALL_COLLISION_AHEAD
    OR A
    JP NZ, STOP_MOVEMENT        ; Hit wall, stop
    
    ; Update position based on current direction
    CALL APPLY_MOVEMENT
    
    ; Update pixel counter
    LD A, (PAC_PIXEL_COUNTER)
    LD B, A
    LD A, (PAC_SPEED)
    ADD A, B
    AND 7                       ; Keep within 0-7 range
    LD (PAC_PIXEL_COUNTER), A
    
    ; Update component with new values
    CALL UPDATE_MOVEMENT_COMPONENT
    RET

STOP_MOVEMENT:
    ; Stop movement and clear current direction
    XOR A
    LD (PAC_CURRENT_DIR), A
    CALL UPDATE_MOVEMENT_COMPONENT
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Check if direction change is possible
;; Input: Current direction state in variables
;; Output: Updates current direction if change is valid
;; Destroys: AF, BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CHECK_DIRECTION_CHANGE:
    LD A, (PAC_DESIRED_DIR)
    OR A
    RET Z                       ; No desired direction
    
    LD B, A                     ; B = desired direction
    LD A, (PAC_CURRENT_DIR)
    CP B
    RET Z                       ; Already moving in desired direction
    
    ; Check if desired direction is opposite to current
    CALL IS_OPPOSITE_DIRECTION
    OR A
    JP NZ, CHANGE_TO_OPPOSITE   ; Allow immediate reverse
    
    ; Check if perpendicular direction is clear
    LD A, B                     ; A = desired direction
    CALL CHECK_WALL_COLLISION_IN_DIRECTION
    OR A
    RET NZ                      ; Can't turn, collision detected
    
    ; Safe to change direction
    LD A, B
    LD (PAC_CURRENT_DIR), A
    XOR A
    LD (PAC_DESIRED_DIR), A     ; Clear desired direction
    RET

CHANGE_TO_OPPOSITE:
    ; Allow immediate direction reversal
    LD A, B
    LD (PAC_CURRENT_DIR), A
    XOR A
    LD (PAC_DESIRED_DIR), A     ; Clear desired direction
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Check if two directions are opposite
;; Input: A = current direction, B = desired direction
;; Output: A = 1 if opposite, 0 if not
;; Destroys: HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
IS_OPPOSITE_DIRECTION:
    LD HL, OPPOSITE_DIR_TABLE
    ADD A, L                    ; A = current direction offset
    LD L, A
    LD A, 0
    ADC A, H
    LD H, A
    LD A, (HL)                  ; A = opposite of current direction
    CP B                        ; Compare with desired
    LD A, 0
    RET NZ                      ; Not opposite
    INC A                       ; A = 1 (opposite)
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Apply movement to position based on current direction
;; Input: Movement state in variables
;; Output: Updates entity position
;; Destroys: AF, BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
APPLY_MOVEMENT:
    LD A, (PAC_CURRENT_DIR)
    ADD A, A                    ; A = direction * 2 (for velocity table)
    LD HL, DIR_VELOCITY_TABLE
    ADD A, L
    LD L, A
    LD A, 0
    ADC A, H
    LD H, A
    
    ; Get velocity values
    LD C, (HL)                  ; vx
    INC HL
    LD B, (HL)                  ; vy
    
    ; Apply speed multiplier
    LD A, (PAC_SPEED)
    LD D, A
    
    ; Calculate vx * speed
    LD A, C
    OR A
    JP Z, APPLY_VY              ; vx is 0
    JP P, APPLY_POSITIVE_VX
    ; Negative vx
    NEG
    CALL MULTIPLY_A_D           ; A = abs(vx) * speed
    NEG                         ; Make negative
    JP STORE_VX
APPLY_POSITIVE_VX:
    CALL MULTIPLY_A_D           ; A = vx * speed
STORE_VX:
    LD C, A                     ; C = final vx
    
APPLY_VY:
    ; Calculate vy * speed
    LD A, B
    OR A
    JP Z, UPDATE_POSITION       ; vy is 0
    JP P, APPLY_POSITIVE_VY
    ; Negative vy
    NEG
    CALL MULTIPLY_A_D           ; A = abs(vy) * speed
    NEG                         ; Make negative
    JP STORE_VY
APPLY_POSITIVE_VY:
    CALL MULTIPLY_A_D           ; A = vy * speed
STORE_VY:
    LD B, A                     ; B = final vy

UPDATE_POSITION:
    ; Update X position
    LD HL, (PAC_POSITION_PTR)
    LD A, (HL)                  ; Current X
    ADD A, C                    ; Add vx
    LD (HL), A
    
    ; Update Y position
    INC HL
    LD A, (HL)                  ; Current Y
    ADD A, B                    ; Add vy
    LD (HL), A
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Multiply A by D (simple 8-bit multiplication)
;; Input: A = multiplicand, D = multiplier
;; Output: A = result (truncated to 8 bits)
;; Destroys: E
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
MULTIPLY_A_D:
    LD E, A
    XOR A
MULTIPLY_LOOP:
    ADD A, E
    DEC D
    JP NZ, MULTIPLY_LOOP
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Check wall collision in current direction
;; Input: Current position and direction in variables
;; Output: A = 1 if collision, 0 if clear
;; Destroys: BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CHECK_WALL_COLLISION_AHEAD:
    LD A, (PAC_CURRENT_DIR)
    JP CHECK_WALL_COLLISION_IN_DIRECTION

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Check wall collision in specified direction
;; Input: A = direction to check
;; Output: A = 1 if collision, 0 if clear
;; Destroys: BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CHECK_WALL_COLLISION_IN_DIRECTION:
    ; Get current position
    LD HL, (PAC_POSITION_PTR)
    LD E, (HL)                  ; X position
    INC HL
    LD D, (HL)                  ; Y position
    
    ; Calculate tile position to check based on direction
    CP DIRECTION_LEFT
    JP Z, CHECK_LEFT_TILE
    CP DIRECTION_RIGHT
    JP Z, CHECK_RIGHT_TILE
    CP DIRECTION_UP
    JP Z, CHECK_UP_TILE
    CP DIRECTION_DOWN
    JP Z, CHECK_DOWN_TILE
    
    ; Invalid direction
    XOR A
    RET

CHECK_LEFT_TILE:
    LD A, E
    SUB 8                       ; Check tile to the left
    LD E, A
    JP CHECK_TILE_AT_POSITION

CHECK_RIGHT_TILE:
    LD A, E
    ADD 16                      ; Check tile to the right (entity width)
    LD E, A
    JP CHECK_TILE_AT_POSITION

CHECK_UP_TILE:
    LD A, D
    SUB 8                       ; Check tile above
    LD D, A
    JP CHECK_TILE_AT_POSITION

CHECK_DOWN_TILE:
    LD A, D
    ADD 16                      ; Check tile below (entity height)
    LD D, A
    JP CHECK_TILE_AT_POSITION

CHECK_TILE_AT_POSITION:
    ; Convert pixel position to tile coordinates
    LD A, E
    SRL A
    SRL A
    SRL A                       ; Divide by 8 for tile X
    LD E, A
    
    LD A, D
    SRL A
    SRL A
    SRL A                       ; Divide by 8 for tile Y
    LD D, A
    
    ; Check collision layer at tile position
    CALL GET_COLLISION_TILE     ; Returns tile value in A
    OR A
    RET Z                       ; No collision (empty tile)
    
    ; Check if tile is solid (basic check - you may need more complex logic)
    AND #F0                     ; Get high nibble (family ID)
    CP #10                      ; Solid family ID
    LD A, 0
    RET NZ                      ; Not solid
    INC A                       ; A = 1 (collision)
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Get collision tile at coordinates
;; Input: E = tile X, D = tile Y
;; Output: A = tile value
;; Destroys: BC, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
GET_COLLISION_TILE:
    ; This function should access the collision layer data
    ; Implementation depends on how your collision map is stored
    ; For now, return 0 (no collision) as placeholder
    XOR A
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Update rotation based on current direction
;; Input: Current direction in variables
;; Output: Updates rotation component if present
;; Destroys: AF, BC, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
UPDATE_PACMAN_ROTATION:
    ; Get rotation component
    LD A, (PAC_CURRENT_ENTITY)
    LD C, COMP_ID_ROTATE
    CALL GET_ENTITY_COMPONENT
    LD A, H
    OR L
    RET Z                       ; No rotation component
    
    ; Set rotation based on current direction
    LD A, (PAC_CURRENT_DIR)
    CP DIRECTION_RIGHT
    JP Z, SET_ROTATION_0
    CP DIRECTION_UP
    JP Z, SET_ROTATION_90
    CP DIRECTION_LEFT
    JP Z, SET_ROTATION_180
    CP DIRECTION_DOWN
    JP Z, SET_ROTATION_270
    RET                         ; No direction, no change

SET_ROTATION_0:
    XOR A
    LD (HL), A                  ; 0 degrees
    INC HL
    XOR A
    LD (HL), A                  ; Facing right
    RET

SET_ROTATION_90:
    LD A, 90
    LD (HL), A                  ; 90 degrees
    INC HL
    LD A, 1
    LD (HL), A                  ; Facing up
    RET

SET_ROTATION_180:
    LD A, 180
    LD (HL), A                  ; 180 degrees
    INC HL
    LD A, 2
    LD (HL), A                  ; Facing left
    RET

SET_ROTATION_270:
    LD A, 270
    LD (HL), A                  ; 270 degrees
    INC HL
    LD A, 3
    LD (HL), A                  ; Facing down
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Update pacMovement component with current values
;; Input: Movement state in variables
;; Output: Updates component in memory
;; Destroys: AF, BC, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
UPDATE_MOVEMENT_COMPONENT:
    LD HL, (PAC_MOVEMENT_PTR)
    
    ; Update fields in component
    INC HL                      ; Skip speed (read-only)
    LD A, (PAC_CURRENT_DIR)
    LD (HL), A                  ; currentDirection
    INC HL
    LD A, (PAC_DESIRED_DIR)
    LD (HL), A                  ; desiredDirection
    INC HL
    LD A, (PAC_PIXEL_COUNTER)
    LD (HL), A                  ; pixelCounter
    
    ; Set velocities for physics system if present
    INC HL
    LD A, (PAC_CURRENT_DIR)
    CALL GET_VELOCITY_FOR_DIRECTION
    LD (HL), C                  ; velocityX
    INC HL
    LD (HL), B                  ; velocityY
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Get velocity values for direction
;; Input: A = direction
;; Output: C = vx, B = vy
;; Destroys: HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
GET_VELOCITY_FOR_DIRECTION:
    ADD A, A                    ; A = direction * 2
    LD HL, DIR_VELOCITY_TABLE
    ADD A, L
    LD L, A
    LD A, 0
    ADC A, H
    LD H, A
    LD C, (HL)                  ; vx
    INC HL
    LD B, (HL)                  ; vy
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Read player input and return direction
;; Input: None
;; Output: A = direction (0 if no input)
;; Destroys: HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
READ_PLAYER_INPUT:
    ; Read MSX keyboard or joystick input
    ; This is a placeholder - implement based on your input system
    
    ; Example keyboard scan (you'll need to adapt this)
    LD A, 8                     ; Scan row 8 (arrow keys)
    CALL SCAN_KEYBOARD_ROW
    
    BIT 4, A                    ; Left arrow
    JP NZ, INPUT_LEFT
    BIT 7, A                    ; Right arrow  
    JP NZ, INPUT_RIGHT
    BIT 5, A                    ; Up arrow
    JP NZ, INPUT_UP
    BIT 6, A                    ; Down arrow
    JP NZ, INPUT_DOWN
    
    XOR A                       ; No input
    RET

INPUT_LEFT:
    LD A, DIRECTION_LEFT
    RET
INPUT_RIGHT:
    LD A, DIRECTION_RIGHT
    RET
INPUT_UP:
    LD A, DIRECTION_UP
    RET
INPUT_DOWN:
    LD A, DIRECTION_DOWN
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Placeholder function for keyboard scanning
;; Input: A = row to scan
;; Output: A = key state
;; Destroys: None
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
SCAN_KEYBOARD_ROW:
    ; Implement MSX keyboard scanning here
    ; This is a placeholder that returns no keys pressed
    XOR A
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Working variables for Pac-Man movement system
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
PAC_CURRENT_ENTITY:         DB 0
PAC_MOVEMENT_PTR:           DW 0
PAC_POSITION_PTR:           DW 0
PAC_INPUT_PTR:              DW 0

PAC_SPEED:                  DB 0
PAC_CURRENT_DIR:            DB 0
PAC_DESIRED_DIR:            DB 0
PAC_PIXEL_COUNTER:          DB 0

; Component ID constants (define these based on your ECS system)
COMP_ID_PACMOVEMENT         EQU 12  ; Adjust this value
COMP_ID_POSITION            EQU 0   ; Adjust this value
COMP_ID_PLAYER_INPUT        EQU 6   ; Adjust this value
COMP_ID_ROTATE              EQU 13  ; Adjust this value